package com.phoenix.business.service;import com.lowagie.text.*;import com.lowagie.text.pdf.PdfWriter;import com.phoenix.business.domain.*;import com.phoenix.business.repository.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import java.io.*;
@Service @RequiredArgsConstructor public class ReceiptService {private final BrandingAssets brandingAssets;private final PaymentRepository payments;private final BusinessSettingsRepository settings;public byte[] create(Long id)throws Exception{Payment p=payments.findById(id).orElseThrow();BusinessSettings s=settings.findById(1L).orElseThrow();try(ByteArrayOutputStream out=new ByteArrayOutputStream()){Document d=new Document(PageSize.A5,36,36,36,36);PdfWriter.getInstance(d,out);d.open();try{byte[] logo=brandingAssets.read(s.getLogoUrl());if(logo!=null){Image image=Image.getInstance(logo);image.scaleToFit(72,72);d.add(image);}}catch(IOException ignored){/* Missing or invalid optional logo must not prevent payment receipts. */}Font title=new Font(Font.HELVETICA,18,Font.BOLD);d.add(new Paragraph(s.getGymName(),title));d.add(new Paragraph(s.getAddress()==null?"":s.getAddress()));d.add(new Paragraph("Receipt: "+p.getReceiptNumber()));d.add(Chunk.NEWLINE);d.add(new Paragraph("Member: "+p.getMember().getName()+" ("+p.getMember().getMemberCode()+")"));d.add(new Paragraph("Plan: "+p.getPlanNameSnapshot()));d.add(new Paragraph("Membership period: "+p.getPeriodStart()+" to "+p.getPeriodEnd()));d.add(new Paragraph("Amount: "+s.getCurrency()+" "+p.getAmount()));d.add(new Paragraph("Payment method: "+p.getMethod()));d.add(new Paragraph("Payment date: "+p.getPaymentDate()));d.add(new Paragraph("Received by: "+p.getReceivedBy().getDisplayName()));if(s.getTaxIdentifier()!=null)d.add(new Paragraph("Tax/GST ID: "+s.getTaxIdentifier()));d.add(Chunk.NEWLINE);if(s.getReceiptFooter()!=null)d.add(new Paragraph(s.getReceiptFooter()));d.close();return out.toByteArray();}}}
